import wrtc from '@roamhq/wrtc';
async function gather(pc){if(pc.iceGatheringState==='complete')return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Relay ICE gathering timed out')),4000);pc.onicegatheringstatechange=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);pc.onicegatheringstatechange=null;resolve();}};});}
// A local WebRTC relay exercises real SCTP/DTLS and endpoint encryption. It
// deliberately has no audio key. It does not stand in for a live SFU test.
export function relay(){const sessions=new Map(),ciphertexts=[];return {ciphertexts,api:member=>async(action,body={})=>{let item=sessions.get(member);if(action==='connect'){const pc=new wrtc.RTCPeerConnection({iceServers:[]});item={pc,ready:false};sessions.set(member,item);item.bootstrap=pc.createDataChannel('server-events');await pc.setLocalDescription(await pc.createOffer());await gather(pc);return {ok:true,sessionDescription:{type:pc.localDescription.type,sdp:pc.localDescription.sdp}};}if(action==='answer'){await item.pc.setRemoteDescription(body.sessionDescription);return {ok:true};}if(action==='open'){item.channel=item.pc.createDataChannel('encrypted-audio',{negotiated:true,id:2,ordered:false,maxPacketLifeTime:120});item.channel.binaryType='arraybuffer';item.channel.onmessage=({data})=>{if(member==='publisher'){const bytes=new Uint8Array(data);ciphertexts.push(bytes.slice());for(const [id,peer]of sessions)if(id!=='publisher'&&peer.ready&&peer.channel?.readyState==='open')peer.channel.send(bytes);}else if(data==='ready')item.ready=true;};return {ok:true,channelId:2,ordered:false,maxPacketLifeTime:120};}return {ok:true};},close(){for(const item of sessions.values()){if(item.channel){item.channel.onmessage=null;item.channel.close();}item.bootstrap.close();item.pc.onicegatheringstatechange=null;item.pc.close();}sessions.clear();}};}
